package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class ChunkingStrategiesTest {@Test void headingStrategyPreservesLocationAndPolicyLimits(){ParsedSection section=new ParsedSection("Rules","第一段内容。第二段内容。第三段内容。",3,Arrays.asList("Root","Rules"),10,40);ParsedDocument document=new ParsedDocument("Handbook","application/pdf",Collections.singletonList(section),Collections.emptyList(),Collections.emptyList());ChunkingPolicy policy=new ChunkingPolicy("HEADING_AWARE",18,4,2,true,false,"ROW",false);java.util.List<com.hmdp.ai.domain.knowledge.ChunkFragment> chunks=new HeadingAwareChunkingStrategy().chunk(document,policy);assertTrue(chunks.size()>=2);assertEquals(3,chunks.get(0).getPage());assertEquals("Root / Rules",chunks.get(0).getHeadingPath());}}
